             '결과알려', '결과보여', '결과줘',
             '이제됐', '이제괜찮', '그만물어', '그만묻', '질문그만', '그만하고',
             #  ★ 2026-08-04 실측 추가 — 「뭐라도 빨리 시작할 수 있는 거 없나요」가
             #    사실상 착지 요청인데 안 잡혔다. '빨리'·'바로' 단독은 여전히 안 넣는다
             #    (「빨리 돈 벌고 싶어요」는 조건 진술이다) — **'시작·할수있는것'과 붙을 때만.**
             '빨리시작', '바로시작', '당장시작', '지금시작할',
