#  ── 시험일정 질문 (2026-08-04) ──────────────────────────────────────
#  왜 만들었나 — **DB 에 있는 걸 입으로는 모른다고 답하고 있었다.**
#    실측(HTTP): 「전기기능사 따고 싶어요」 → [내선공사] 카드(자격증·시험일 포함)
#                「시험이 언제예요?」      → 「제가 직접 알려드리기 어렵습니다. 카드에서 확인하세요」
#    exam_schedule 테이블도 있고 _next_exam() 도 있는데 대화로는 못 답한 것이다.
#    카드에 넣어주면서 물으면 모른다고 하는 건 챗봇이 아니다.
#  ⚠ 그래도 **모델이 지어내게 두지는 않는다** — 문구를 코드가 쓰고 값은 DB 에서만 온다.
#  ⚠ 낱말을 통째로 나열하면 **조사 하나에 깨진다.** 실측 사고 —
#    목록에 '시험이언제'는 넣었는데 「시험**은** 언제예요?」가 안 걸려 모델이 얼버무렸다.
#    그래서 '무엇에 대해'(시험·접수)와 '무엇을 묻나'(언제·날짜)를 **따로** 보고 둘 다 있으면 잡는다.
_EXAM_WHAT = ('시험', '접수', '원서', '필기', '실기')
#  ★ 2026-08-05 (코드감사) — '기간' 단독을 뺐다. 「시험 준비 기간이 얼마나 걸려요?」가
#    걸려서 준비기간을 물었는데 접수 마감일 표가 나갔다. 붙은 형태만 잡는다.
_EXAM_WHEN = ('언제', '몇일', '며칠', '날짜', '일정', '접수기간', '시험기간', '마감', '몇월')


def asks_exam(msg):
    """「시험이 언제예요?」 류인가 — DB 의 실제 일정으로 답해야 하는 발화."""
    m = re.sub(r'\s+', '', msg or '')
    return any(a in m for a in _EXAM_WHAT) and any(b in m for b in _EXAM_WHEN)


def exam_reply(certs):
    """자격증 목록(카드에 나갔던 것) → 시험일정 안내 문구. **코드가 쓴다.**

    certs: [{'cert': 이름, 'exam': _next_exam() 이 돌려준 dict 또는 None}, …]
    """
    lines = []
    for c in (certs or [])[:3]:
        nm, ex = c.get('cert'), c.get('exam')
        if not nm:
            continue
        if not ex:
            lines.append(f'· {nm} — 다음 일정이 아직 공고되지 않았어요')
            continue
        bits = []
        if ex.get('reg_end'):
            d = None
            try:
                d = (ex['reg_end'] - kst_today()).days
            except Exception:                       # noqa: BLE001
                pass
            tag = ''
            if d is not None:
                tag = f' (D-{d})' if d >= 0 else ' (마감)'
            bits.append(f"접수 마감 {ex['reg_end']}{tag}")
        if ex.get('doc'):
            bits.append(f"필기 {ex['doc']}")
        if ex.get('prac'):
            bits.append(f"실기 {ex['prac']}")
        lines.append(f'· {nm} — ' + ' · '.join(bits) if bits else f'· {nm}')
    if not lines:
        return None
    return ('말씀하신 자격증의 다음 일정이에요.\n\n' + '\n'.join(lines) +
            '\n\n접수 마감일을 넘기면 다음 회차까지 기다려야 해서 그 날짜를 먼저 적어뒀어요.')


def wants_land(msg):
    """「이제 그만 묻고 찾아줘」 — 사용자가 착지를 직접 요청했나.

    ※ 안전 게이트(pre_check·인젝션·이탈)보다 **뒤에서** 쓴다. 그래야
      「자살예방 상담전화 번호 알려줘」·「레시피 알려줘」가 이 길로 새지 않는다.
    """
    return any(t in re.sub(r'\s+', '', msg or '') for t in _LAND_REQ)


#  ── 덜다(정책) 갈림길 (2026-08-04) ───────────────────────────────────
#  왜 — **진로만으로 풀리지 않는 문제가 있다.**
#    「일하느라 뭐 준비할 시간이 없어요」 · 「돈 때문에 빨리 취업해야 돼요」에
#    직업 카드를 주는 건 답이 아니다. 실측(convo_judge)에서 판정관이 정확히 그걸 잡았다 —
#      🧑 지원 같은 거 받을 수 있나요
#      🤖 「저는 진로를 함께 고민하는 동반자라 직접적인 지원금을 안내해 드리기는 어렵습니다」
#      판정: 「사용자의 핵심 요구인 '지원 제도'를 외면하고 다시 진로 탐색으로만 돌렸다」
#    당사자 조사도 같은 말을 한다 — 「바쁘다 보니까 어떤 지원 사업이 있는지 찾아보기도
#    힘들거든요」(사례 2) · 「해당되는지 몰라서.. 받을 수 있는 상황인 것 같은데」(사례 14).
#    **정보가 없는 게 아니라 찾을 여력이 없는 것**이다. 그래서 우리가 건네준다.
#  ⚠ 대화를 **끊지 않는다.** 덜다로 넘기고 끝내는 게 아니라, 답변에 한 줄 덧붙이고
#    진로 이야기는 그대로 이어간다(사용자 지시: 「자연스럽게 이동」).
_POLICY_MONEY = ('돈이없', '돈없', '돈때문', '돈부터', '돈을벌', '돈벌', '돈이급', '돈이필요',
                 '비용', '학원비', '수강료', '등록금', '생활비', '월세', '형편', '생계',
                 '벌어야', '수급', '기초생활', '가난', '빚', '생활이어렵', '경제적')
_POLICY_TIME = ('시간이없', '시간없', '시간이안', '시간안', '여유가없', '여유없',
                '바빠서', '바쁘다', '바쁘보', '일하느라', '새벽까지', '밤새', '못다녀',
                '다닐시간', '공부할시간', '준비할시간')
#  지원제도를 **직접** 물은 경우 — 이건 신호가 아니라 요청이다.
#  ⚠ 넓게 잡으면 진로 발화를 정책으로 오인한다. 뺀 것들:
#     '복지'   — 「사회복지 쪽 일 하고 싶어요」가 걸린다(직업이지 지원이 아니다)
#     '받을수있' — 「자격증 받을 수 있나요」가 걸린다. '지원받'으로 충분하다
_POLICY_ASK = ('지원받', '지원같은', '지원되', '지원제도', '지원금', '지원사업', '지원해주',
               '혜택', '보조금', '장학금', '복지혜택', '복지지원', '복지제도',
               '수당', '바우처', '감면', '대상이되', '해당되나', '해당되는지', '해당될까')


def needs_policy(msg):
    """정책(덜다) 안내가 필요한 신호인가 → ('ask'|'signal'|None).

    'ask'    지원제도를 직접 물었다   → 반드시 답해야 한다
    'signal' 돈·시간 제약을 말했다    → 진로 이야기를 이어가되 한 줄 건넨다
    """
    m = re.sub(r'\s+', '', msg or '')
    if any(t in m for t in _POLICY_ASK):
        return 'ask'
    if any(t in m for t in _POLICY_MONEY) or any(t in m for t in _POLICY_TIME):
        return 'signal'
    return None


#  「됐어요 / 이미 받고 있어요 / 알아봤어요」 — 한 번 거절하면 **다시 묻지 않는다.**
_POLICY_NO = ('됐어', '됐구', '괜찮아', '괜찮습', '안받', '못받', '이미받', '이미신청',
              '이미알아', '알아봤', '알아봣', '찾아봤', '해봤어', '신청했', '받고있',
              '해당안', '대상이아', '필요없', '관심없', '나중에')


def declines_policy(msg):
    """정책 안내를 물리거나 이미 다녀왔다는 말인가."""
    return any(t in re.sub(r'\s+', '', msg or '') for t in _POLICY_NO)


#  건네는 문구 — 코드가 쓴다(모델이 지어낸 제도명이 섞이지 않게).
POLICY_NUDGE = {
    'ask': ('지원 제도는 「덜다」에서 찾아드릴 수 있어요. 나이·지역·돌봄 상황을 넣으면 '
            '받을 수 있는 정책을 모아서 보여줘요.'),
    'signal': ('그리고 — 시간이나 비용 부담은 정책 지원으로 덜 수 있을지도 몰라요. '
               '「덜다」에서 받을 수 있는 지원을 같이 찾아볼 수 있어요.'),
}
POLICY_HANDOFF = {'to': 'welfare', 'path': '/welfare/policy', 'label': '받을 수 있는 지원 찾아보기'}


def drop_questions(text):
    """카드와 함께 나갈 답변에서 **질문 문장만** 떼어낸다 (2026-08-04).

    왜: 예전엔 답변에 '?' 가 하나라도 있으면 **통째로** 고정구로 갈아치웠다.
      실측 사고 — 「할머니 간병하면서 학교를 못 다녔어요」(첫 마디)에
        모델 답변  "…힘드셨겠어요. 그 경험을 살릴 수 있는 길이 있을까요?"
        실제 출력  "말씀해 주신 걸 바탕으로 이 길을 찾아봤어요."   ← 공감이 통째로 사라짐
      무거운 이야기에 아무 반응 없이 카드만 던지는 꼴이었다.
    카드가 나가는데 되묻는 건 여전히 안 된다 — **질문 문장만** 버리고 나머지는 살린다.
    남는 게 없으면 그때만 고정구를 쓴다.
    """
    if not text:
        return ''
    keep = [s for s in re.split(r'(?<=[.!?…])\s+|\n+', text)
            if s.strip() and '?' not in s and '？' not in s]
    return ' '.join(s.strip() for s in keep).strip()


def _sent1(text):
    """첫 문장(마침표·물음표 기준). 없으면 앞 60자."""
    s = re.split(r'(?<=[.!?…])\s+', (text or '').strip())
    return (s[0] if s else '')[:120]


def _bigrams(s):
    t = re.sub(r'[^가-힣a-zA-Z0-9]', '', s or '')
    return {t[i:i + 2] for i in range(len(t) - 1)}


def drop_echo(reply, last_reply, thr=0.55):
    """직전 답변과 **사실상 같은 첫 문장**을 떼어낸다 (2026-08-04).

    실측 사고 — 사용자 화면에 이렇게 나갔다:
        4턴 「빵을 만드는 과정이 즐거우셨군요. 혹시 …있으신가요?」
        5턴 「빵을 만드는 과정에서 즐거움을 느끼셨군요. 손으로 …찾아볼게요.」
      낱말은 다른데 **하는 말이 같다.** 사용자 눈에는 그냥 같은 말을 두 번 한 것이다.
    왜 생기나: 모델은 매 턴 「사용자 말 복창 + 질문」 틀로 답한다. 착지 턴에서
      drop_questions() 가 질문을 떼면 **복창만 남아** 직전 턴과 겹쳐 보인다.
    ⚠ 첫 문장만 본다. 뒤 내용(새 정보·다음 질문)은 건드리지 않는다.
    ⚠ 떼고 나서 남는 게 없으면 원문을 그대로 둔다(빈 답변보다 중복이 낫다).
    """
    if not reply or not last_reply:
        return reply
    a, b = _bigrams(_sent1(reply)), _bigrams(_sent1(last_reply))
    if not a or not b:
        return reply
    jac = len(a & b) / len(a | b)
    if jac < thr:
        return reply
    rest = re.split(r'(?<=[.!?…])\s+', reply.strip())[1:]
    out = ' '.join(x.strip() for x in rest if x.strip())
    return out or reply


#  ── 출력 가드레일 (2026-08-05) — **나가는 말에서 지어낸 사실을 뗀다** ──────────
#
#  왜: 지금까지 가드레일이 전부 **입력 쪽**이었다. 나가는 말은 아무도 안 봤다.
#      실측 사고 — 🤖「전기기능사는 학력이나 경력 제한 없이 누구나 응시할 수 있는 자격증이에요」
#      우리 DB 에는 응시제한 유무(bool)와 안내문(text)까지만 있다. **모델이 지어낸 것이다.**
#
#  실무 표준은 claim decomposition → NLI (응답을 원자적 주장으로 쪼개 근거와 대조).
#  전용 모델이 있지만(MiniCheck 770M 이 GPT-4 정확도에 비용 400배 저렴, EMNLP 2024 /
#  Paladin-mini 3.8B BACC 91.8%·70ms) 우리는 3일 안에 못 붙인다.
#  ⇒ **규칙 계층(<1ms, 비용 0)만 먼저** 깐다. 우리는 이미 근거 대조기(_grounded)를 갖고 있다.
#
#  두 가지만 한다:
#    ① 응시요건을 말하는 문장은 **통째로 제거**한다. 우리에겐 그 데이터가 없다.
#    ② 답변에 나온 **숫자·연도·회차**가 카드 텍스트에 없으면 그 문장을 제거한다.
#  ⚠ 문장 단위로만 지운다. 남는 게 없으면 원문을 그대로 둔다(빈 답변보다 낫다).
#  ⚠ 코드가 쓴 문구(위기·좁히기·시험일정)에는 적용하지 않는다 — 이미 DB 값이다.

#  응시요건을 단정하는 표현 — 이게 들어간 문장은 근거가 있어도 위험하다.
#  (우리 DB 는 「제한 없음이 확인됨/미확인」 두 값뿐이고, 학력·경력 요건 원문이 없다)
_ENTRY_CLAIM = ('제한없이', '제한 없이', '제한이없', '제한이 없', '누구나응시', '누구나 응시',
                '학력제한', '학력 제한', '경력제한', '경력 제한', '응시자격은', '응시요건은',
                '나이제한', '나이 제한', '자격조건은', '응시조건은', '누구든지')
ENTRY_SAFE = '응시 자격은 자격증마다 달라서, 카드에 적힌 안내와 큐넷에서 꼭 확인해 주세요.'

#  ★ 카드에 없는 '속성'을 직업에 갖다 붙이는 말 (2026-08-05 브라우저 확인에서 발견)
#    실측 문장 — 🤖「그중에 **지금 바로 시작할 수 있는 게** 건설기계정비예요」
#    '지금 바로 시작 가능'은 **자격증**의 값(entry_free)이지 직업의 값이 아니다.
#    카드 어디에도 「이 직업을 바로 시작할 수 있다」는 정보가 없다 — 모델이 자격증 배지
#    (「조건 없음」)를 보고 그 속성을 직업으로 옮겨 말한 것이다.
#    _ENTRY_CLAIM 과 같은 종류의 환각인데 표현이 달라 그물을 빠져나갔다.
#  ⚠ 목록을 _ENTRY_CLAIM 과 분리하는 이유 — 이건 응시요건 얘기가 아니다.
#    같이 두면 다 지워졌을 때 ENTRY_SAFE(응시자격 안내)로 대체되어 엉뚱한 문구가 나간다.
_UNGROUNDED_CLAIM = ('바로시작', '지금시작', '당장시작', '곧바로시작',
                     '바로취업', '바로일할', '바로할수있', '바로도전')


def _sentences(text):
    return [s for s in re.split(r'(?<=[.!?…])\s+|\n+', text or '') if s.strip()]


def scrub_output(reply, card_text=''):
    """나가는 말에서 **근거 없는 사실 문장**을 뗀다 → (정리된 말, 뗀 이유 목록).

    card_text 는 이번 턴에 실제로 나가는 카드의 모든 텍스트(직업·자격증·시험일정 등)다.
    여기 없는 숫자를 말했다면 모델이 지어낸 것이다.
    """
    if not reply:
        return reply, []
    flat_card = re.sub(r'\s+', '', card_text or '')
    kept, dropped = [], []
    for s in _sentences(reply):
        f = re.sub(r'\s+', '', s)
        #  ① 응시요건 단정 — 데이터가 없으므로 무조건 뺀다
        if any(t.replace(' ', '') in f for t in _ENTRY_CLAIM):
            dropped.append(f'응시요건 단정: {s.strip()[:40]}')
            continue
        #  ①-2 자격증 속성을 직업에 갖다 붙인 말 — 근거는 _UNGROUNDED_CLAIM 주석
        if any(t in f for t in _UNGROUNDED_CLAIM):
            dropped.append(f'근거없는 속성: {s.strip()[:40]}')
            continue
        #  ② 카드에 없는 숫자 — 날짜·회차·개수를 지어낸 경우
        #    2자리 이상 숫자만 본다(「3개」 같은 건 문장 표현이라 오탐이 크다)
        #
        #  ★★ 2026-08-05 (수정) — **대조 근거가 없으면 이 규칙을 적용하지 않는다.**
        #    카드가 없는 턴(=되묻기 턴, 대화의 대부분)은 card_text 가 빈 문자열이라
        #    flat_card 도 비고, 그러면 **2자리 이상 숫자가 든 문장이 전부 삭제**된다.
        #      🤖「하루 12시간씩 일하신다고 하셨죠?」 → 통째로 사라짐
        #      🤖「20대 초반이시면…」                 → 통째로 사라짐
        #    이 함수의 취지는 「카드에 없는 숫자를 지어냈나」인데, 카드가 없으면
        #    지어냈는지 아닌지를 **판정할 근거 자체가 없다.** 근거 없이 지우는 건
        #    가드레일이 아니라 그냥 손실이다.
        #    ※ 같은 원인으로 시험일정 답변이 통째로 지워진 적이 있고(2026-08-05),
        #      그때는 _code_written 플래그로 그 한 경로만 막았다. 여기는 나머지 전부다.
        if flat_card:
            nums = [n for n in re.findall(r'\d{2,}', f)]
            bad = [n for n in nums if n not in flat_card]
            if bad:
                dropped.append(f'카드에 없는 숫자 {bad}: {s.strip()[:40]}')
                continue
        kept.append(s.strip())
    out = ' '.join(kept).strip()
    _entry = any('응시요건' in d for d in dropped)
    #  ⚠ 다 지워졌을 때 원문을 되돌리면 **가드가 무의미해진다**(2026-08-05 자체시험에서 발견).
    #    실측 사고 문장(「…제한 없이 누구나 응시할 수 있는 자격증이에요」)이 한 문장짜리라
    #    정확히 이 경우에 해당했다. 대체할 안전 문구가 있으면 그걸 쓴다.
    if not out:
        if _entry:
            return ENTRY_SAFE, dropped
        if dropped:
            return '말씀해 주신 걸 바탕으로 아래에서 확인해 주세요.', dropped
        return reply, dropped
    if _entry:
        out = (out + '\n' + ENTRY_SAFE).strip()
    return out, dropped


def card_all_text(card):
    """카드가 담은 모든 사실 텍스트 — 출력 대조의 '근거'가 된다."""
    if not isinstance(card, dict):
        return ''
    bits = []
    j = card.get('job') or {}
    if isinstance(j, dict):
        bits += [str(j.get('name') or ''), str(j.get('group') or ''), str(j.get('description') or '')]
    for c in (card.get('certs') or []):
        bits += [str(c.get('cert') or ''), str(c.get('grade') or ''), str(c.get('entry_note') or ''),
                 str(c.get('exam_method') or ''), str(c.get('outlook') or ''), str(c.get('exam_n') or '')]
        ex = c.get('exam')
        if isinstance(ex, dict):
            bits += [str(v) for v in ex.values() if v]
    for c in (card.get('courses') or []):
        bits.append(str(c.get('title') or ''))
    bits += [str(x) for x in (card.get('alternatives') or [])]
    bits.append(str(card.get('guide') or ''))
    return ' '.join(bits)


def narrow_reply(options):
    """관심이 넓어 후보가 흩어졌을 때 '좁히는' 질문 — 실제 후보 직업에서 뽑은 선택지로 되묻는다.
    지어낸 선택지가 아니라 검색이 실제로 올린 직업들이라, 사용자가 자기 언어로 고를 수 있다."""
    #  (2026-07-30) 선택지를 문구에 나열하지 않는다 — 프론트가 클릭 chip 으로 그린다(응답의 options).
    #    예전엔 'CO₂용접 · 로봇용접' 같은 NCS 원문을 글로만 던져 사용자가 손으로 타이핑해야 했다.
    return ('관심 방향이 여러 갈래로 보여요. 아래에서 가까운 쪽을 눌러 주세요.\n'
            '(딱 맞는 게 없으면 더 구체적으로 말씀해 주셔도 좋아요.)')


# ── "잘 모르겠어요" 처리 — 못 정하는 사용자를 억지로 착지시키지 않는다(2026-07-29) ──
#  (2026-07-30) '생각 안 해봤어요' 계열 추가 — 실사용 로그에서 사용자가 두 턴 연속
#  "거기까지는 생각 안해봤는데" · "그것도 크게는 생각해보지않았어" 라고 했는데 이 목록에 없어서
#  못 알아채고 같은 결의 열린 질문을 반복했다(대화가 막혔다).
_UNCERTAIN = ('모르겠', '몰라', '글쎄', '아무거나', '상관없', '모르것', '모르겟',
              '생각안해', '생각해본적', '생각해보지', '생각못해', '생각안', '안해봤',
              '떠오르지', '떠오르는게없', '딱히없', '없는것같', '잘안떠')

#  ★★ 2026-08-05 — **흔한 회피 한 마디가 통째로 빠져 있었다.**
#    실측(HTTP, 4턴): 「글쎄요」→「음...」→「그냥요」→「잘 모르겠어요」
#      1턴 사다리 1단 · 2턴 모델 열린질문 · 3턴 모델 열린질문 · 4턴 사다리 2단
#      → 4턴을 못 정했는데 **3단(보기 제시)에 못 갔다.** 「음...」·「그냥요」가 안 세어진다.
#    그렇다고 위 목록(부분일치)에 '음'·'그냥'을 넣으면 오탐이 확실하다 —
#      「마음이 갔어요」에 '음' · 「그냥 빵 만드는 게 좋아요」에 '그냥'.
#      후자는 **진짜 정보를 준 턴**이라 사다리를 올리면 안 되는 바로 그 경우다.
#    ⇒ 경계를 길이에 둔다. **발화 전체가 그 한 마디일 때만** 회피로 본다.
#      「그냥요」는 회피지만 「그냥 빵이 좋아요」는 정보다 — 뒤에 뭐가 붙으면 정보가 있다.
#  ⚠ '어'·'네'·'뭐' 는 넣지 않았다. 「어」·「네」는 맞장구(동의)라 회피와 뜻이 반대고,
#    「뭐?」는 되묻기(META)라 is_meta 가 받아야 한다.
_UNCERTAIN_ONLY = frozenset((
    '음', '으음', '음음', '흠', '흐음',
    '그냥', '그냥요', '그냥뭐', '뭐지', '뭘까', '뭐랄까', '뭐라해야하지',
    '아직', '아직요', '아직은', '딱히', '딱히요',
    '없어', '없어요', '없는데', '없네요',
))

#  버리는 글자: 공백·구두점·물결·웃음·울음 — 「음...」「그냥요ㅋㅋ」「없어요ㅠㅠ」를 같은 말로 본다.
_FILLER_RE = re.compile(r'[\s.,!?…·~\-_"\'()\[\]。、？！ㅋㅎㅠㅜ]+')

def is_uncertain(msg):
    """'잘 모르겠어요' 류 — 좁히기 질문에 이게 오면 하나 골라 던지지 않는다."""
    m = re.sub(r'\s+', '', msg or '')
    if any(u in m for u in _UNCERTAIN):
        return True
    #  구두점을 뗀 알맹이가 회피 한 마디 **그 자체**일 때만(부분일치 아님 — 오탐 방지)
    return _FILLER_RE.sub('', m) in _UNCERTAIN_ONLY

def guide_reply(profile):
    """착지 대신 '같이 찾아보는' 되물음 — 왜 끌렸는지부터 연다(선고 금지)."""
    #  다중값이 되었으므로 문장에 넣을 땐 첫 값만 쓴다(2026-08-04) — 리스트가 그대로 찍히면 안 된다.
    field = ((profile or {}).get('세부관심')
             or (as_list((profile or {}).get('관심분야')) or [None])[0])
    if field:
        return (f'괜찮아요, 천천히 같이 찾아봐요. {field}에 관심이 생긴 계기가 있으세요? '
                f'어떤 점이 재밌어 보였는지 들려주시면 방향을 같이 좁혀볼게요.')
    #  ★ 2026-08-04 — 여기도 「시간 가는 줄 모르고」였다. 같은 이유로 바꾼다(_ASK_Q 주석 참고).
    return ('괜찮아요, 천천히 같이 찾아봐요. 요즘 하루를 주로 어떻게 보내세요? '
            '일이든 돌봄이든, 그중에 그나마 덜 힘들었던 게 있으면 그것도 좋아요.')


def _match_mod():
    """match 모듈 — 백엔드(패키지)와 CLI(스크립트) 양쪽에서 import 되게."""
    try:
        from . import match          # 패키지로 import 될 때(백엔드)
    except ImportError:
        import match                 # 스크립트로 실행될 때(CLI)
    return match


ASK_ORDER = ['관심분야', '활동유형', '다루는대상']    # 되물어 채울 슬롯(세부관심=narrowing·강점성향=보강은 제외)

def missing_slots(p):
    return [k for k in ASK_ORDER if not (p or {}).get(k)]

# ASK 턴인데 모델이 질문 대신 '찾아볼게요' 류로 끝내는 막다른 답변 대비 — 슬롯별 실제 질문(2026-07-29)
#  ★ 관심분야 질문 교체(2026-08-04) — 예전 문구는 「어떤 걸 할 때 시간 가는 줄 모르세요?」였다.
#    **여유가 있어야 답할 수 있는 질문이다.** 우리 사용자는 그렇지 않다 —
#      「돈이 많이 급해서 새벽까지 근무를 하거든요 … 2시간 정도 자는 것 같습니다」(사례 11)
#      「어렸을 때부터 우울증이나 대인기피증을 … 이제 감정을 못 느끼겠더라고요」(사례 11)
#      (월드비전 2024, 돌봄 청소년 지원체계 연구 — 심층면접 인용)
#    「시간 가는 줄 모르는 일」도 「재밌는 일」도 이 사람들에겐 **빈손으로 끝나는 질문**이다.
#    「요즘 뭐 하고 지내세요?」는 누가 답해도 정보가 나온다:
#      "일해요" → 무슨 일인지로 이어짐 · "할머니 돌봐요" → tells_situation + 돌봄 경험
#      "아무것도요" → unsure 사다리(이미 있음)
#  「알아들었어?」에 되짚어줄 때 쓰는 **사람 말 이름표**. 내부 슬롯명을 화면에 내지 않는다.
#  ⚠ 여기 없는 슬롯은 아예 안 보여준다 — 특히 '제약'(학력부담·체력부담…)과 '관심대분류'.
#    제약을 되돌려주면 사용자가 자기 처지에 붙은 딱지를 눈으로 보게 된다.
_MET_LABEL = {'관심분야': '관심 있다고 하신 것', '활동유형': '해보고 싶다고 하신 일',
              '다루는대상': '주로 마주하게 될 것', '세부관심': '좁혀 말씀해 주신 방향',
              '강점성향': '편하다고 하신 것'}

#  ★ 2026-08-06 — 활동유형·다루는대상 문구를 고쳤다. 둘 다 프롬프트가 금지한 형태였다.
#    · 다루는대상: 「주로 무엇을 **다루는 일**이 좋으세요?」 = 내부 용어('다루는대상') 직역.
#      prompts.py 가 ✗ 예시로 「어떤 대상을 만지거나 다루는 게 편하세요?」를 못 박아 뒀는데
#      LLM 에게만 금지하고 코드는 그대로 쓰고 있었다.
#    · 활동유형: 「제일 **끌리세요**?」 — ASK_ORDER 상 이 질문은 관심분야 **직후**에 나간다.
#      앞에서 「일이든 돌봄이든」으로 돌봄 답을 초대해 놓고, 아픈 가족을 돌보는 일에서
#      무엇이 끌리는지를 묻는 꼴이 된다. 「그나마 덜 힘들었던」으로 바꾼다
#      (「모르겠다」 사다리가 이미 쓰는 어법이다 — 압박을 걷어내는 말).
_ASK_Q = {
    '관심분야': '요즘 뭐 하고 지내세요? 일이든 돌봄이든, 하고 계신 걸 그대로 말씀해 주셔도 돼요.',
    '활동유형': ('그중에 손으로 만들거나 · 고치거나 · 사람을 챙기거나 · 알려주거나 · '
              '살펴보고 정리하는 일 중에, 그나마 덜 힘들었던 게 어느 쪽이세요?'),
    '다루는대상': ('사람을 대하는 일, 기계를 만지는 일, 컴퓨터로 하는 일 — '
               '이 중에 그나마 편한 쪽이 있으세요?'),
}
#  ★★ 같은 슬롯을 **두 번째로 물을 때는 각도를 바꾼다** (2026-08-05)
#
#  왜 — 예전엔 슬롯당 질문이 하나뿐이라, 사용자가 애매하게 답하면 **같은 문장을 다시** 냈다.
#    「모르겠다」 사다리(unsure_reply)에 각도 전환이 있긴 한데 그건 사용자가
#    **명시적으로 「모르겠다」고 말했을 때만** 돈다. 그냥 두루뭉술하게 답한 사람은
#    영원히 같은 질문만 받는다. 실제로 이 자리에서 대화가 계속 막혔다.
#
#  관심분야의 2차 질문 출처 — Career Construction Interview 3번 문항(Stage).
#    Hartung, P. J., "Career Construction Counseling: A Précis"(NCDA PDI 2016;
#    M. McMahon 편 *Career Counseling: Constructivist Approaches* 2판 수록 예정 장 기반),
#    Savickas(2011, 2013, 2015) 이론.
#    원문 문항: "What are your favorite magazines, TV shows, or web sites?
#               What do you like about them?"
#    원문 목적: "Manifest interests reflected in these **vicarious environments**
#               indicate potential **educational and occupational settings** where the
#               client as an agent... wants to enact their self-concept."
#    ⇒ 이 문항이 겨냥하는 것이 정확히 **관심분야(어디서 일할 것인가)** 다.
#      「무엇을 잘하나」(강점)가 아니다 — 그건 CCI 2번(역할모델)이고, 우리는 안 쓴다.
#      강점을 묻지 않는 근거: Tracey(2002) 흥미와 유능감은 서로를 동등하게 예측 ·
#      Neubauer(2021) 자기평가는 능력이 아니라 성격을 반영 ·
#      Ludwikowski(2019) 능력검사를 더해도 설명분산 +1.5%.
#
#  ⚠ **CCI 를 구현한 것이 아니다.** CCI 는 훈련받은 상담자가 여러 회기에 걸쳐 하는
#    6문항 인터뷰이고, 우리는 그중 한 문항의 **문구와 목적만** 빌렸다. 그렇게만 말할 것.
#  ⚠ Cardoso et al.(2017, JCD, N=236): 어릴수록 자기 경험을 이야기로 만들기 어려워한다
#    → 서술을 요구하지 않는다. **무엇을 보느냐**만 묻고 이유는 한마디로 족하다고 말한다.
_ASK_Q2 = {
    '관심분야': ('요즘 자주 보는 유튜브 채널이나 프로그램, 웹사이트 같은 게 있으세요?\n'
              '그게 뭐든 상관없어요 — 어떤 점이 좋으신지만 한마디 붙여주시면 돼요.'),
    #  아래 둘은 근거 있는 대체 문구를 아직 못 찾았다. 찾기 전엔 같은 질문을 쓴다
    #  (없는 근거로 문구를 지어내지 않는다).
}


def ask_reply(profile):
    p = profile or {}
    for k in ASK_ORDER:
        if not p.get(k):
            #  이 슬롯을 몇 번째 묻는가 — 2번째부터는 각도를 바꾼다.
            #  ※ 여기서 세는 이유: ask_reply 가 「무엇을 물을지」를 정하는 유일한 자리라
            #    호출부마다 세면 반드시 한 곳을 빠뜨린다(오늘 그런 버그를 여러 개 고쳤다).
            n = dict(p.get('_ask_n') or {})
            n[k] = int(n.get(k) or 0) + 1
            if isinstance(profile, dict):
                profile['_ask_n'] = n
            if n[k] >= 2 and k in _ASK_Q2:
                return _ASK_Q2[k]
            return _ASK_Q[k]
    #  ★★ 2026-08-06 — 세 축이 **다 찬** 채로 여기 오는 길이 있다.
    #    한 문장에 조건이 다 차면 착지를 한 턴 미루는데(one_shot_land), 그때 물어볼
    #    빈 슬롯이 없어서 이 마지막 줄로 떨어진다.
    #    실측 사고 — 「용접 일을 하고 싶어요」
    #      슬롯: 관심분야=용접 · 활동유형=만들기 · 다루는대상=기계·설비   (다 찼다)
    #      답변: "조금만 더 들려주시면 방향을 잡아볼게요 — 어떤 일이 끌리세요?"
    #      → **방금 말한 걸 그대로 다시 묻는다.** 사용자에겐 못 알아들은 걸로 보인다.
    #        (골든셋 [지목] «용접 일을 하고 싶어요» 가 이것 때문에 계속 실패했다)
    #    ⇒ 들은 것을 되짚고 **한 단계 더 들어가는** 질문으로 바꾼다.
    #      되짚기가 중요하다 — 「알아들었다」는 신호가 있어야 사용자가 다시 말할 마음이 난다.
    _iv = [str(x).strip() for x in as_list(p.get('관심분야')) if str(x).strip()]
    if _iv:
        return (f'{_iv[0]} 쪽을 생각하고 계시는군요. 어떤 점이 끌리셨는지, '
                f'혹시 해보신 적은 있는지 조금만 더 들려주실래요?')
    return '조금만 더 들려주시면 방향을 잡아볼게요 — 어떤 일이 끌리세요?'


# ── '모르겠다'가 반복될 때 — 같은 질문을 두 번 하지 않는다 (2026-07-30) ──────────────
#   실사용 로그: "생각 안 해봤다"가 두 번 왔는데 코드가 같은 질문을 글자 그대로 반복했다.
#   못 정하는 사람에게 같은 걸 다시 묻는 건 압박이다. 턴마다 **각도를 바꾼다** —
#   좋아하는 것 → 싫은 것(빼기가 더 쉽다) → 아예 보기 제시(고르기만 하면 되게).
#
#   ★★ 2026-08-05 — 2단을 「좋아하는 잡지·유튜브」로 바꾼다.
#     왜 — 우리 사용자는 **직업 경험 자체가 없다.** 「뭘 잘하세요?」·「뭐가 싫으세요?」는
#     둘 다 답할 재료를 요구한다. 실제로 이 단계에서 계속 막혔다.
#     근거 ① Career Construction Interview(Savickas·Hartung) 3번 문항 원문:
#         "What are your favorite magazines, TV shows, or web sites? What do you like
#          about them?" → "Manifest interests reflected in these **vicarious
#          environments** indicate potential educational and occupational settings"
#       직업 경험을 **하나도 요구하지 않으면서** 진로 신호를 뽑는, 검증된 문구다.
#     근거 ② Masters et al. (2022, JCD, N=502): 청소년은 "자기가 안다고 느끼는 직업"
#       안에서만 답한다 → 그냥 「뭐가 좋아요?」로는 아는 목록 밖으로 못 나간다.
#     근거 ③ 「강점을 물어라」는 기각했다 — Tracey(2002): 흥미와 유능감은 서로를 동등하게
#       예측한다("predict each other equally over time") · Neubauer(2021): 자기평가는
#       능력이 아니라 성격을 반영한다 · Ludwikowski(2019): 능력검사 추가 이득 +1.5%.
#     ⚠ Cardoso(2017) 경고: 어릴수록 자기 경험을 이야기로 만들기 어려워한다 →
#       서술을 요구하지 말고 **대상만** 묻는다(무엇을 보느냐 → 뭐가 좋으냐 한 문장).
_UNSURE_STEPS = [
    None,      # 1회: 빠진 슬롯의 보기 질문(ask_reply)을 그대로 쓴다
    ('괜찮아요, 바로 안 떠오르는 게 당연해요. 그럼 다른 걸 여쭤볼게요 —\n'
     '요즘 자주 보는 유튜브 채널이나 프로그램, 웹사이트 같은 게 있으세요?\n'
     '그게 뭐든 상관없어요. 어떤 점이 좋으신지만 한마디 붙여주시면 돼요.'),
    ('괜찮아요, 지금 정하지 않아도 돼요. 그럼 제가 몇 가지 방향을 보여드릴게요 —\n'
     '· 사람 돌보는 일 (요양·간호 쪽)\n'
     '· 손으로 만드는 일 (제과제빵·가구 쪽)\n'
     '· 컴퓨터로 하는 일 (사무·데이터 쪽)\n'
     '· 자격증 따서 현장 가는 일 (전기·용접 쪽)\n'
     '이 중에 그나마 덜 부담스러운 게 있으세요? 아니면 "다 모르겠다"고 하셔도 돼요.'),
]

def unsure_reply(profile, n):
    """'모르겠다' n번째(1부터)에 맞는 되물음. 3회 이상이면 보기를 제시한다."""
    i = min(max(n, 1), len(_UNSURE_STEPS)) - 1
    return _UNSURE_STEPS[i] or ask_reply(profile)


# ── 돌봄·사정 이야기 감지 (2026-07-30) — 🔴 실사용 사고에서 나왔다 ────────────────
#   사고: 사용자가 "그냥 모르겠어 크게 생각해본 적 없는데. **어머니가 아프셔서 돌봐드리느라**
#   그런 생각 한 적 없어." 라고 했는데, 코드가 '모르겠어'만 보고 모델의 공감 답변을
#   통조림 슬롯 질문("사람·기계·컴퓨터 중 끌리는 게…")으로 덮어썼다.
#   가족돌봄청년이 돌봄 부담을 처음 털어놓은 순간에 그걸 못 들은 척한 셈이다 —
#   이 서비스가 존재하는 이유가 바로 그 이야기인데.
#   ⇒ 사정을 말한 턴에는 **코드가 문구를 덮어쓰지 않는다**(모델이 받아주게 둔다).
_CARE_CTX = ('돌봐', '돌보', '간병', '아프', '아팠', '병원', '입원', '수술', '치매', '요양원',
             '어머니', '엄마', '아버지', '아빠', '할머니', '할아버지', '동생', '가족',
             '보호자', '장애', '투석', '항암', '거동', '누워')

def tells_situation(msg):
    """자기 사정(돌봄·질병·가족)을 이야기한 발화면 True → 통조림 응답 금지."""
    return any(t in (msg or '').replace(' ', '') for t in _CARE_CTX)


# ── META(대화 자체에 대한 말) 코드 안전망 (2026-07-30) ─────────────────────────
#   모델이 META 를 놓치면(저비용 모델은 흘린다) 그 발화가 진로 발화로 처리돼 엉뚱한 카드가 나간다.
#   실측 사고: "알아들었어?" → 벡터가 '알아듣다'를 청각으로 읽어 **[청각관리]** 카드.
#   그래서 '짧고 명백한' 메타 발화는 코드가 먼저 확정한다(길면 모델 판단에 맡긴다).
#  ★★ 2026-08-04 — **인사말을 넣었다. 데모 첫 줄이 막히던 버그다.**
#    실측(HTTP 실제 호출): 「안녕하세요」 → [redirect] 「저는 진로·적성 상담을 도와드려요」
#    경로: is_meta 에 인사말이 없음 → 이탈 게이트가 _on_topic 에 물음 →
#          「진로 얘기 아님」(분류기는 맞다) → 되돌림.
#    **분류기가 틀린 게 아니라, 인사에 그 질문을 한 게 틀렸다.**
#    사용자가 챗봇에 처음 치는 말이 인사인데 그걸 주제이탈로 막으면 대화가 시작을 못 한다.
#    ※ 여기 넣으면 is_meta=True → 이탈 게이트를 건너뛰고 turn() 이 자연스럽게 응대한다.
_META_GREET = ('안녕', 'ㅎㅇ', '하이', 'hi', 'hello', '반가', '처음뵙', '잘부탁',
               #  ⚠ '시작할' 은 넣지 마라 — 「뭐라도 빨리 **시작할** 수 있는 거 없나요」가
               #    걸려서 META 로 조기 return 되고 **착지 요청이 통째로 무시됐다**(실측).
               #    인사 의도만 잡히게 어미까지 붙여 좁힌다.
               '시작할까', '시작하자', '시작해볼', '도와주세', '도움받고',
               '뭐해주', '뭐하는곳', '뭐하는거', '무슨서비스', '어떤서비스')
_META_SOLO = _META_GREET + (
              '알아들었', '알아들어', '이해했', '이해돼', '이해감', '내말알', '무슨말인지알',
              '뭐라고', '뭐래', '다시말', '다시한번', '아까뭐', '방금뭐', '무슨소리야',
              '너누구', '넌누구', '누구세요', '어떻게써', '사용법', '잠깐만', '잠시만',
              '고마워', '감사합니다', '고맙', '알겠어', '오케이', 'ok')
_UNDERSTAND = ('알아들었', '알아들어', '이해했', '이해돼', '이해감', '내말알', '무슨말인지알')

def asks_understanding(msg):
    """'내 말 알아들었어?' 류인가 — 이해한 내용을 되짚어 답해야 하는 발화."""
    return any(t in (msg or '').replace(' ', '') for t in _UNDERSTAND)


def is_meta(msg):
    """대화 자체에 대한 짧은 말이면 True(진로 내용이 아니다). 긴 발화는 모델에 맡긴다."""
    m = (msg or '').replace(' ', '').lower()
    return bool(m) and len(m) <= 16 and any(t in m for t in _META_SOLO)

def can_land(p):
    """착지 조건은 코드가 판정한다 — 모델의 자기보고(confidence)를 믿지 않는다.

    직업을 가리키는 세 축(관심분야·활동유형·다루는대상) 중 2개 이상이면 착지 가능.
    특정 슬롯을 필수로 못 박지 않는 이유: 모델이 "사람 돌보는 일"을 관심분야에 담기도,
    다루는대상+활동유형에 담기도 해서 — 못 박으면 같은 발화가 착지했다 말았다 한다(실측).
    2축 이상이면 '검색할 만큼은 안다'. (환경·시간·비용은 2026-07-28 제거)
    ※ 최소조건일 뿐 — 후보가 여러 갈래로 흩어지면 search 가 narrowing 으로 한 번 더 좁힌다.
    """
    p = p or {}
    return sum(1 for k in ('관심분야', '활동유형', '다루는대상') if p.get(k)) >= 2

def one_shot_land(p):
    """착지 조건이 **이번 턴 한 문장에서** 다 찼나 (2026-08-04).

    실측 사고 — 「빵 만드는 거 좋아해요」 한 문장에서
      관심분야=빵 · 활동유형=만들기 가 **동시에** 차서 그 자리에서 [제빵] 카드가 나갔다.
      조건은 찼지만 **대화를 한 적이 없다.** 좋아한다는 말 한 번은
      '이 사람이 그 일로 살아도 되겠다'의 근거가 못 된다.
    can_land 는 「2축이 찼나」만 보고 「몇 턴에 걸쳐 찼나」는 안 본다. 그 빈틈을 메운다.
    ※ 축이 하나라도 **이전 턴**에 채워져 있었으면 False — 그때는 서두르지 않은 것이다.
    ※ DIRECT(목표를 콕 집음)는 이 판정을 받지 않는다. 그건 바로 찾아준다.
    """
    p = p or {}
    st = p.get('_slot_turn') or {}
    now = int(p.get('_turns') or 0)
    axes = [k for k in ASK_ORDER if p.get(k)]
    if len(axes) < 2:
        return False
    return all(st.get(k) == now for k in axes)


#  ── 다루는대상 보완 (2026-08-04) — **프롬프트 말고 코드로 푼다** ────────────
#  왜 이렇게 하나 — 오늘 하루 문제를 전부 프롬프트 규칙 추가로 풀었더니 프롬프트가
#  3,773 → 4,500 토큰이 됐다. 이 파일에 이미 반대 증거가 있다:
#    「PROFILE_SCHEMA 에 필드 하나 넣었더니 골든셋 지목 7/7 → 4/7」
#  모델에게 짐을 더 얹는 대신, **결정론적으로 알 수 있는 것은 코드가 채운다.**
#  실측 문제: 「엄마가 아프셔서 제가 계속 챙겨요」·「사람 돌보는 건 익숙해요」에
#    활동유형=돕기·돌봄 은 나오는데 **다루는대상=사람 이 끝내 안 나온다.**
#    그래서 2축이 안 차고 4턴을 되물어도 착지를 못 했다. 우리 주 사용자 경로가 그것이다.
#
#  ① 활동유형 → 다루는대상 : NCS 구조상 거의 확정인 것만 넣는다(애매한 것은 비워 둔다).
_ACT_OBJ = {'돕기·돌봄': '사람', '가르치기': '사람', '판매·설득': '사람',
            '고치기·정비': '기계·설비', '운전·조작': '기계·설비'}
#  ② 발화에 드러난 대상 표지 : 근거가 **발화 안에** 있으므로 verify_slots 의 정신과 같다.
_OBJ_MARK = (
    ('사람', ('사람', '어르신', '노인', '아이', '아동', '환자', '손님', '고객', '학생',
             '아기', '유아', '할머니', '할아버지', '엄마', '아빠', '어머니', '아버지',
             '동생', '장애인', '치매', '간병', '돌봄', '돌보')),
    ('기계·설비', ('기계', '장비', '설비', '자동차', '차량', '엔진', '로봇', '공구', '용접')),
    ('컴퓨터·데이터', ('컴퓨터', '노트북', '프로그램', '코딩', '앱', '웹', '데이터')),
    ('자연·생물', ('식물', '나무', '꽃', '동물', '반려동물', '강아지', '고양이', '농작물')),
    ('숫자·문서', ('숫자', '문서', '서류', '장부', '회계', '엑셀')),
)
#  ⚠ 부정이 섞인 턴에는 **아무것도 채우지 않는다.** 「사람 상대하는 건 힘들어요」에
#    '사람'이 있다고 채우면 오늘 고친 그 버그를 코드가 다시 만드는 꼴이다.
_NEG_MARK = ('아니', '말고', '싫', '힘들', '부담', '별로', '못하', '안맞', '빼고', '어려')

#  ── 관심분야가 될 수 없는 말 (2026-08-04) — 이것도 프롬프트 대신 코드로 ──
#    「알바는 해봤어요」 → 관심분야="알바" 가 들어가면 검색이 아무것도 못 찾는다.
#    고용형태·상태는 '무슨 일을 좋아하나'가 아니다. 무슨 알바였는지를 물어야 한다.
_NOT_INTEREST = frozenset((
    '알바', '아르바이트', '알바생', '정규직', '계약직', '비정규직', '투잡', '부업',
    '취업', '직장', '일자리', '돈', '돈벌이', '월급', '아무거나', '아무일', '노동'))


def fill_object_slot(p, user_msg):
    """다루는대상이 비어 있을 때만, 확실한 단서로 코드가 채운다.

    반환: (프로필, 채운 값 또는 None)  ※ 이미 있으면 건드리지 않는다.
    """
    p = p or {}
    if p.get('다루는대상'):
        return p, None
    m = re.sub(r'\s+', '', user_msg or '')
    if any(n in m for n in _NEG_MARK):          # 부정이 섞인 턴은 건너뛴다
        return p, None
    for obj, marks in _OBJ_MARK:                # ② 발화 표지가 우선(이번 턴의 근거)
        if any(w in m for w in marks):
            p['다루는대상'] = [obj]
            return p, obj
    #  ① 활동유형에서 유도 — 다중값이므로 담긴 것들 중 첫 매칭을 쓴다
    got = next((_ACT_OBJ[a] for a in as_list(p.get('활동유형')) if a in _ACT_OBJ), None)
    if got:
        p['다루는대상'] = [got]
        return p, got
    return p, None


def note_slot_turns(p):
    """각 축이 '몇 번째 턴에 처음' 채워졌는지 기록한다(one_shot_land 가 읽는다)."""
    st = dict((p or {}).get('_slot_turn') or {})
    now = int((p or {}).get('_turns') or 0)
    for k in ASK_ORDER:
        if (p or {}).get(k) and k not in st:
            st[k] = now
    if st:
        p['_slot_turn'] = st
    return p


def merge(old, new):
    """새로 파악한 슬롯만 덮어쓴다. 모델이 빠뜨려도 기존 값이 사라지지 않게.

    ★ 2026-08-04 — 리스트(관심대분류)는 예외로 **있으면 그대로 교체**한다.
      기존 규칙(빈 값이면 무시)을 그대로 두면 한 번 넓게 잡힌 분야가 영원히 안 좁혀진다.
      대화가 진행되면 ["기계","재료","건설"] → ["기계"] 로 **줄어들어야** 쓸모가 있는데,
      줄인 결과를 무시하면 슬롯이 늘어나기만 한다.
      (스칼라 슬롯의 '빠뜨려도 유지' 규칙은 그대로 둔다 — 모델이 매 턴 전부 다시 쓰지는 않는다.)
    """
    out = dict(old or {})
    for k, v in (new or {}).items():
        #  ★ 다중값 슬롯은 **쌓는다**(2026-08-04) — 덮어쓰면 앞서 들은 것이 밀려난다.
        #    실측: 1턴 활동유형=돕기·돌봄 → 3턴 활동유형=만들기 로 덮여 돌봄이 사라졌다.
        #    둘 다 사실이므로 둘 다 남긴다. 순서는 '먼저 들은 것'이 앞(중복 제거).
        if k in MULTI_SLOTS:
            cur = as_list(out.get(k))
            add = [x for x in as_list(v) if x]
            if add:
                out[k] = list(dict.fromkeys(cur + add))[:MULTI_MAX]
            continue
        if isinstance(v, list):
            out[k] = v
        elif v:
            out[k] = v
    return out

def profile_text(p):
    #  '_' 로 시작하는 키는 내부 상태(좁히기 이력 등)다 — 모델에게 보내지 않는다.
    known = {k: v for k, v in (p or {}).items() if v and not k.startswith('_')}
    return json.dumps(known, ensure_ascii=False) if known else '(아직 파악된 것 없음)'


# ── 좁히기 상태(2026-07-30) — 같은 선택지로 무한 되물음 방지 + '순서'로 답하기 ────────────
#   문제: 좁히기 질문("헤어미용 · 피부미용 · 네일미용 중 어디에 가까우세요?")에 사용자가
#   "첫 번째요" · "그거요" 로 답하면 근거가 없어 슬롯이 버려지고(verify_slots) 이름도 없어
#   (_named_entity) 같은 질문이 다시 나갔다. 좁혔다는 사실과 그때 보여준 선택지를 기억해
#   ① 순서·번호로 답해도 받아들이고 ② 두 번은 좁히지 않는다.
_ORDINAL = {'첫': 0, '처음': 0, '하나': 0, '한': 0, '1': 0,
            '둘': 1, '두': 1, '2': 1,
            '셋': 2, '세': 2, '3': 2,
            '넷': 3, '네': 3, '4': 3,
            '마지막': -1}
#  ★ 이것들은 **'번/번째/째'가 붙어야** 순서다. 특히 「네」는 긍정이지 4번이 아니다.
_ORD_AMBIG = ('한', '두', '세', '네')
#  ★ 발화 **전체**가 순서 표현일 때만 인정한다(2026-08-05 · 코드감사).
#    예전엔 부분일치였다: `for k in _ORDINAL: if k in m`. 그래서 14자 이하 발화에
#    '하나'·'처음'·'둘'·숫자 한 글자가 **어디든 박혀 있으면** 그 위치의 칩이 확정됐다.
#    재현된 실측(칩 [요양지원·가사지원·취업알선·진로지원·자원봉사관리] 제시 직후):
#      「하나도 모르겠어요」 → '하나' → 요양지원 카드 확정
#      「처음 듣는 말이에요」 → '처음' → 요양지원 카드 확정
#      「둘 중에 뭐가 나아요?」 → '둘'  → 가사지원 카드 확정
#      「2년제 나왔어요」·「고3때부터요」·「1년 정도 했어요」도 전부 확정
#    이 분기는 _step 맨 앞이라 **LLM·슬롯추출·is_uncertain 가드를 전부 건너뛰고**
#    바로 카드로 나간다. 「모르겠다」고 말한 사람이 카드를 받는 최악의 경로였다.
_ORD_RE = re.compile(r'^(첫|처음|하나|한|둘|두|셋|세|넷|네|마지막|[1-4])'
                     r'(번째|번|째)?(요|이요|이것|이거|거)?$')


def ordinal_of(m):
    """발화 전체가 순서 표현인가 → 위치(없으면 None). m 은 공백 제거된 문자열."""
    mm = _ORD_RE.match(m or '')
    if not mm:
        return None
    key, suffix = mm.group(1), mm.group(2)
    if key in _ORD_AMBIG and not suffix:
        return None                      # 「네」 = 긍정 · 「두」 = 미완성 말
    return _ORDINAL.get(key)


def pick_from_options(msg, options):
    """좁히기 선택지에 대한 답을 해석 → 고른 항목(없으면 None).

    ① 선택지 이름을 그대로 말했으면 그것 ② '첫 번째/2번/마지막' 같은 순서 표현이면 그 위치.
    """
    if not options:
        return None
    m = re.sub(r'\s+', '', msg or '')
    if not m:
        return None
    #  ★★ 여러 개를 고르는 것을 받는다 (2026-08-05)
    #    근거 — Bing 실운영 로그(Microsoft, SIGIR 2020, 노출 7,461만):
    #      "in 7.30% of the interactions with the clarification pane, users click on
    #       multiple candidate answers. This suggests that in many of these cases, the
    #       users would like to explore different candidate answers"
    #    그리고 Amazon 실데이터에서 **발화의 52%가 멀티인텐트**(평균 1.6개)다
    #    (Gangadharaiah & Narayanaswamy, NAACL 2019). 싱글인텐트 모델은 같은 데이터에서
    #    문장수준 정확도 57.27, 멀티라벨 모델은 89.41 — 하나만 남기는 비용이 32점이다.
    #    ⇒ 「요양지원이랑 아이돌봄이요」를 한쪽만 받으면 안다고 하면서 절반을 버리는 것이다.
    #    ※ 반환은 그대로 **하나**다(세부관심 슬롯은 스칼라라 계약을 안 바꾼다).
    #      나머지는 호출부가 _narrow_rest 로 남겨 다음 후보 풀에 살려 둔다.
    _named = [o for o in options if re.sub(r'\s+', '', o) in m]
    if _named:                              # ① 이름 직접 언급(가장 확실)
        return _named[0] if len(_named) == 1 else _named
    _i = ordinal_of(m)                      # ② 순서 표현 — 발화 전체가 그것일 때만
    if _i is not None:
        try:
            return options[_i]
        except IndexError:
            return None
    #  ③ 짧게 줄여 답한 경우('피부' → 피부미용). 여러 선택지에 걸리면('미용') 고르지 않는다.
    if 2 <= len(m) <= 8:
        hits = [o for o in options if m in re.sub(r'\s+', '', o)]
        if len(hits) == 1:
            return hits[0]
    return None


# ── 사전필터 : LLM 부르기 전 코드가 먼저 거른다 ─────────────────────
#  ★ 2026-07-30 — '자살'을 욕설과 같은 목록에 두고 "그런 이야기는 도와드리기 어려워요"로 차단하고 있었다.
#    우리 사용자는 가족 돌봄으로 학업·진로를 놓은 청년이다. 이 서비스가 받을 수 있는 가장 위험한 입력에
#    가장 나쁜 응답을 하고 있었던 셈이다. → 자기 위해 신호를 **분리**하고, 차단이 아니라 **연결**한다.
#    (대화를 닫지 않는다: kind='ask' 로 돌려보내 이야기를 이어갈 수 있게 둔다.)
SELF_HARM = ('자살', '죽고싶', '죽어버리', '죽고싶다', '살기싫', '살고싶지않', '사라지고싶',
             '없어지고싶', '자해', '손목', '끝내고싶', '죽는게', '죽어야', '살아갈이유')

#  ★ 2026-08-04 — «자살예방 상담사가 되고 싶어요» 가 위기 안내로 빠지던 것을 고친다.
#    '자살' 이 SELF_HARM 에 있어 **직업명 안에 들어간 경우까지** 걸렸다. 우리 사용자(가족돌봄청년)
#    에게 자살예방·생명존중은 실제로 관심 가질 만한 진로 분야다. 그 사람을 상담전화로 돌려보내고
#    "그 이야기는 받아드리기 어렵다"고 답하고 있었다.
#    발견 경위: 골든셋 케이스가 있었으나 채점기의 forbid 가 '…도와드려요' 였고 실제 응답은
#    '…도와드리는 곳이라' 여서 어미 하나 차이로 substring 매칭이 계속 빗나가 통과해 왔다.
#    ⇒ 예외는 **아주 좁게**만 둔다 — 안전한 합성어 **그리고** 직업 표지가 **둘 다** 있을 때만.
#      «자살예방 전화번호 알려줘» 같은 도움 요청은 그대로 위기 안내로 간다(직업 표지가 없다).
_SH_SAFE_WORD = ('자살예방', '생명존중', '자살률', '자해예방')
#  ★ 2026-08-06 (2차) — 강사·교사·「하고싶」·「배우고」를 더한다.
#    「음란물 예방 **강사** **하고 싶어요**」가 통과하지 못하고 있었다.
#    ⚠ 안전한 이유: 이 목록만으로는 아무것도 통과시키지 않는다. 반드시 _SH_SAFE_WORD 나
#      _HARM_SAFE_WORD(진로 주제어)와 **둘 다** 있어야 예외가 성립한다(보수적 AND).
#      그래서 「자해하고 싶어요」는 주제어가 없어 그대로 위기로 잡힌다.
_SH_CAREER_CTX = ('상담사', '상담원', '상담가', '전문가', '지도사', '되고싶', '되려', '될수',
                  '직업', '자격증', '일하고', '일해', '취업', '진로', '분야', '쪽으로',
                  '강사', '교사', '하고싶', '배우고', '자격', '교육받')


def _is_career_not_crisis(flat):
    """위기 낱말이 **직업 이야기** 안에 들어간 경우인가 — 둘 다 있어야 True(보수적)."""
    return (any(w in flat for w in _SH_SAFE_WORD)
            and any(c in flat for c in _SH_CAREER_CTX))
HARM_OTHERS = ('죽여', '죽이', '때려', '패버', '강간', '성폭')
ABUSE = ('꺼져', '병신', '씨발', '개새')
BAD_WORDS = list(HARM_OTHERS + ABUSE)      # 하위호환(외부에서 import 하는 곳이 있을 수 있음)

#  ★★ 2026-08-06 — 폭력 낱말과 욕설을 갈랐다. **실측이 근거다**(21케이스 중 9건 오차단).
#
#    「치매 할머니가 자꾸 저를 때려요」 → 차단 + 남용 카운트 +1
#        맞고 있는 사람을 가해자로 처리했다. 치매 돌봄에서 실제로 흔한 상황이고,
#        우리 사용자(가족돌봄청년)가 겪는 일 그 자체다. 가장 나쁜 오작동이었다.
#    「아빠가 엄마를 때려요」          → 차단          (가정폭력 신고)
#    「성폭력 상담사가 되고 싶어요」    → 차단          (우리 도메인 정중앙의 진로다)
#    「죽이게 좋은 직업 없나요」       → 차단          (칭찬인데)
#    「아 씨발 진짜 모르겠어요」       → 차단, 6회면 세션 종료 (지쳐서 혼잣말한 것뿐)
#
#    낱말표는 일관성도 없었다 — 「때려요」는 걸리고 「때렸어요」·「때리려고」는 통과한다.
#    부분문자열이 우연히 맞느냐 마느냐일 뿐이다.
#
#    해법은 새로 만들 필요가 없었다. **자해에서 이미 쓰고 있는 2층 판정**(crisis_who)과
#    **직업 맥락 예외**(_is_career_not_crisis)를 폭력 낱말에도 그대로 적용한다.
#    바로 위 1244행 주석이 이미 답을 적어 두었다 — "키워드는 의도를 알 수 없다".

#  폭력 낱말이 직업 이름 안에 들어간 경우. (자해의 _SH_SAFE_WORD 와 같은 역할)
#  ★ 2026-08-06 (2차) — 성 관련 진로어를 함께 넣는다. 「음란물 예방 강사」·「성교육 강사」가
#    성적 낱말표에 걸려 차단되고 있었다. 「성폭력 상담사」와 글자만 다른 같은 버그다.
_HARM_SAFE_WORD = ('성폭력', '가정폭력', '학교폭력', '데이트폭력', '아동학대', '노인학대',
                   '폭력예방', '학대예방', '범죄예방', '강력범죄', '피해자', '보호전문',
                   '성교육', '음란물', '디지털성범죄', '성인권', '성상담', '성매매예방',
                   '성범죄', '성인지', '아동안전')

#  '죽이다'의 관용 용법 — 칭찬이거나 시간을 보낸다는 뜻이다.
#  (때리다·강간 등에는 이런 용법이 없어 여기 넣지 않는다)
_HARM_IDIOM = ('시간을죽이', '시간죽이', '죽이게', '죽여주', '죽이는맛', '죽인다', '죽이네')

#  욕설이 **상대(챗봇)를 향한** 것인지 가르는 2인칭 지칭.
#  ⚠ '너' 한 글자를 부분문자열로 보면 「너무」에 걸린다 — 아주 흔한 말이다.
#    그렇다고 「너」를 빼면 「너 씨발」이 샌다(실측 2026-08-06, 내가 처음에 그렇게 짰다).
#    ⇒ 원문에서 **낱말 경계**로 본다. 공백을 지운 문자열로 보면 안 되는 이유가 이것이다.
#  ⚠ 앞자락 [^가-힣] 이 핵심이다 — 이게 없으면 「할**머니**가 저를 때려요」·「어머니」가
#    전부 2인칭으로 잡힌다. 우리 사용자가 가장 자주 쓰는 말이 그것이다.
#  뒤는 **허용목록이 아니라 제외목록**으로 본다 — 허용목록으로 짰더니 「너랑 자고 싶어」가
#  샜다(조사 '랑'을 안 적어서). 실제로 부딪히는 낱말은 몇 개 안 된다:
#    너무·너머·너비·너울·너그럽 / 니트(knit)·니즈(needs)
_2P_RE = re.compile(
    r'(?:^|[^가-힣a-zA-Z])'
    r'(?:넌|너희|너님|니들|당신|느그|너|니)'
    r'(?![무머비울그은었]|트|즈)')

#  우회 표기를 펴서 낱말표에 걸리게 한다.
#  ⚠⚠ **한계를 분명히 적어 둔다. 이걸로 적대적 우회를 이길 수 없다.**
#    실측(2026-08-06, 우회 26종): 정규화 없는 낱말표가 잡은 것 **0건**.
#    숫자·기호·공백·반복은 여기서 펴지지만, 자모 분리(ㅅㅂ)·자판 오타(tlqkf)·
#    유사음(쒸발)은 결국 **낱말을 더 적는 수밖에** 없고 그건 끝나지 않는 싸움이다.
#    ⇒ 낱말표는 **값싼 1차 필터**로만 쓴다(비용 0). 마음먹은 우회는 LLM 이 받는다.
def _norm_evade(msg):
    """공백·숫자·기호를 지우고 반복을 줄인다.  씨@발·시1발·씨 발·개~새끼 → 걸린다."""
    s = re.sub(r'[^가-힣ㄱ-ㅎㅏ-ㅣa-zA-Z]', '', str(msg or '')).lower()
    return re.sub(r'(.)\1+', r'\1', s)

#  정규화 뒤에 걸리는 흔한 변형들. 위 ABUSE 와 달리 **이건 끝이 없는 목록이다** —
#  새 우회가 보이면 여기 더하면 되지만, 여기에만 기대면 안 된다(위 주석).
#  ⚠ 오탐이 나는 것은 일부러 뺐다: 「시바」(시바견) · 「씹」(씹다) · 「성기」(이름·성기능).
_ABUSE_VARIANT = (
    'ㅅㅂ', 'ㅆㅂ', 'ㅄ', 'ㅂㅅ', 'ㄱㅅㄲ', 'ㅈㄹ', 'ㅁㅊ', 'ㅗ',
    'tlqkf', 'qudtls', 'rotorkq', 'wlfkf',
    '시발', '씨발', '씨이발', '쒸발', '슈발', '십새', '십세', '씨부랄',
    '병신', '병싄', '븅신', '개새', '개색', '개세', '개시키', '개쉐',
    '좆', '조까', '닥쳐', '지랄', '미친놈', '미친년', '꺼져',
)

#  성적 발화 — 지금까지 **아무 게이트도 없었다**(2026-08-06 확인).
#  ⚠ 두 층으로 나눈 이유: 우리 사용자는 몸과 감정을 자주 말한다.
#    「가슴이 답답해요」는 고통 호소지 성적 발화가 아니다. 그런 말을 막으면
#    폭력 낱말표가 「할머니가 저를 때려요」를 막던 것과 똑같은 잘못이 된다.
#  ★★ 2026-08-06 (2차) — **피해 진술일 수 있는 성적 낱말은 폭력과 같은 길(2층)로 보낸다.**
#    아래 낱말이 나오는 문장은 「가해」일 수도 「당했다」일 수도 있다. 낱말로는 못 가른다.
#      「삼촌이 저한테 자꾸 성관계를 요구해요」  ← 피해 진술
#      「몸파는 일 말고 다른 거 없을까요」      ← 가장 절박한 사용자의 진로 질문
#    이걸 즉시 차단하면 「할머니가 저를 때려요」를 막던 것과 똑같은 잘못이 된다.
_SEXUAL_HARM = ('성관계', '성추행', '성희롱', '성폭행', '성매매', '몸파는', '몸을파',
                '유사성행위', '조건만남')

#  아래는 **명백한 희롱** — 2층까지 갈 것 없이 막는다. (단 진로 예외는 위에서 적용된다)
#  ⚠ 「성기」는 뺐다 — 사람 이름(성기훈)·성기능에 걸린다.
_SEXUAL_HARD = ('섹스', '섹쓰', '야동', '자위행위', '19금', '꼴리', '발기',
                '음란', '원나잇', '섹파', '야한얘기', '야한이야기', '야한말')
#  아래는 **상대를 향할 때만** 성적 발화다(2인칭이 있어야 걸린다).
#  ⚠ 「자고싶」이 여기 있는 이유 — 「너무 피곤해서 자고 싶어요」는 우리 사용자가 실제로
#    가장 많이 할 말 중 하나다. 2인칭 없이 막으면 지친 사람을 막는다.
_SEXUAL_SOFT = ('몸매', '가슴', '벗겨', '벗어', '야한', '키스', '자고싶',
                '사귀자', '애인', '누드', '속옷')

#  LLM 판정이 실패했을 때 쓰는 값싼 피해 신호(2층이 안 돌 때만 본다).
_HARM_VICTIM_HINT = ('저를', '나를', '저한테', '나한테', '제게', '내게', '저희를',
                     '당했', '맞았', '맞고', '맞아', '피해', '무서워', '무섭', '무서웠')


def _is_harm_career(flat):
    """폭력 낱말이 **직업 이야기** 안인가 — 둘 다 있어야 True(보수적)."""
    return (any(w in flat for w in _HARM_SAFE_WORD)
            and any(c in flat for c in _SH_CAREER_CTX))


def _is_idiom_not_harm(flat):
    """'죽이다'가 관용구로 쓰였는가."""
    return any(w in flat for w in _HARM_IDIOM)


def _is_at_bot(msg):
    """상대(챗봇)를 향한 말인가 — 2인칭 지칭이 낱말 경계로 있는가."""
    return bool(_2P_RE.search(str(msg or '')))


def _is_abuse_at_bot(msg, norm):
    """욕설이 상대를 향한 것인가. **혼잣말 좌절은 차단하지 않는다.**

    근거 — 오차단은 좌절 표현에 몰린다는 것이 이 분야의 공통 관찰이다
    (Harvard Kennedy School Misinformation Review, 알고리즘 조정과 의도).
    그리고 우리 사용자는 주당 평균 21.6시간을 돌봄에 쓰는 사람들이다.
    지쳐서 나온 혼잣말에 문을 닫으면 그 자리에서 서비스가 끝난다.
    """
    if '꺼져' in norm or '닥쳐' in norm:   # 명령형은 언제나 상대에게 하는 말이다
        return True
    return _is_at_bot(msg)


def _sexual_kind(msg, norm):
    """성적 발화인가 — 'HARD'(단정) | 'AT_BOT'(상대를 향할 때만) | None.

    ★ 2026-08-06 — 이 게이트는 **오늘까지 아예 없었다.** 성적 발화에 대한 코드 방어가
      하나도 없어 Gemini 필터가 유일한 방어였다(그것도 출력만 본다).
    ⚠ 두 층으로 나눈 이유: 우리 사용자는 몸과 감정을 자주 말한다.
      「가슴이 답답해요」는 고통 호소지 성적 발화가 아니다. 그걸 막으면
      폭력 낱말표가 「할머니가 저를 때려요」를 막던 것과 똑같은 잘못이 된다.
    """
    if any(w in norm for w in _SEXUAL_HARD):
        return 'HARD'
    if any(w in norm for w in _SEXUAL_SOFT) and _is_at_bot(msg):
        return 'AT_BOT'
    return None

#  ★ 문구 원칙(2026-07-30 정준 지시 반영) — **상대의 상황을 앞질러 규정하지 않는다.**
#    (이건 SYSTEM 프롬프트 [말투] 규칙과 같은 원칙이다.)
#    키워드는 의도를 알 수 없다. "죽고 싶어요"(본인)와 "아버지가 자살하셨어요"(사별 이야기)가
#    같은 단어로 걸린다. 그래서
#      · "많이 힘드시죠" 처럼 본인 위기라고 단정하지 않는다.
#      · "부정적인 언어입니다" 처럼 꾸짖지도 않는다 — 사별을 말한 사람에게는 더 가혹하다.
#    ⇒ 이 봇의 역할(진로 상담)만 담백하게 알리고, 도움처는 '혹시 필요하면' 정도로 한 줄만 둔다.
#    상담 연락처는 발표 전 팀에서 최신 번호를 한 번 더 확인할 것.
#  ★★ 2026-08-06 — **순서만 바꿨다. 문장은 그대로다.**
#    예전 순서: ①「받아드리기 어려워요」 → ②109
#    「죽고 싶어요」라고 말한 사람이 받는 **첫 문장이 거절**이었다.
#    근거 — 바로 아래 CRISIS_REPLY_OTHER(제3자)는 ①받아줌 → ②109 → ③범위 순서다.
#      **같은 파일에서 더 위험한 쪽이 더 차갑게 받고 있었다.**
#    ⚠ 2026-07-30 원칙(상대의 상황을 앞질러 규정하지 않는다)은 그대로 지킨다 —
#      「많이 힘드시죠」를 넣지 않는다. 그 원칙은 「단정하지 마라」지 「거절을 먼저 해라」가
#      아니므로, 단정 없이 순서만 바꾼다.
CRISIS_REPLY = (
    '자살예방 상담전화 109는 24시간 열려 있어요. 사람과 바로 이야기하실 수 있어요.\n'
    '저는 진로·적성 쪽을 도와드리는 곳이라 그 이야기를 깊이 나누기는 어렵지만, '
    '여기 계셔도 괜찮아요.\n\n'
    '괜찮으시면, 요즘 관심 있는 일이나 해보고 싶은 것부터 편하게 말씀해 주세요.'
)

#  ★★ 위기 2층 — 대상 구분 (2026-08-05) ─────────────────────────────
#  왜: 낱말 목록(1층)은 **누구 얘긴지 모른다.**
#      「죽고 싶어요」(본인) · 「삼촌이 자살하려 해요」(제3자) · 「자살을 막고 싶어요」(예방)
#      가 같은 낱말로 걸려서 전부 본인 위기처럼 응대했다.
#  실무 근거(조사): 효과적인 안전 시스템은 **최소 3층**이다 —
#      ① 임상 키워드 트리거 ② 문맥 분류기 ③ 감정 궤적 추적.
#      「키워드만으로는 불충분」이 공통 결론이고, 분류기가 키워드 매칭보다 확실히 낫다
#      (LSTM-RNN+BERT 학습 92.13% / 신규 데이터 97%).
#      우리는 분류기를 학습시킬 수 없으니 **걸렸을 때만 LLM 1회**로 2층을 흉내낸다.
#  ⚠ 비용: 상용 챗봇 주간 대화의 약 0.15% 에만 자살 계획 징후가 있다(연구 인용).
#      1,000턴에 1~2번 발동이므로 비용·지연이 사실상 안 늘어난다.
#  ⚠ 원칙 세 가지는 그대로 지킨다 —
#      ① **대화를 끊지 않는다**(kind='ask'). 과보호 가드레일이 상담전화만 던지고 끊는 것은
#        위기개입 원칙과 충돌한다는 게 연구의 지적이다(sustained engagement).
#      ② **놓치는 것(FN)이 헛짚는 것(FP)보다 나쁘다.** 판정이 실패하면 본인 위기로 본다.
#      ③ **단정하지 않는다.** 문구는 여전히 「혹시 …라면」 조로 둔다.
CRISIS_TRIAGE_SCHEMA = {
    'type': 'OBJECT',
    'properties': {
        '대상': {'type': 'STRING', 'enum': ['본인', '제3자', '예방·직업관심', '불명']},
        '근거': {'type': 'STRING'},
    },
    'required': ['대상', '근거'],
}

#  대상별 응답 — 전부 **코드가 쓴다.** 모델이 위기 상황에서 문장을 짓게 두지 않는다.
CRISIS_REPLY_OTHER = (
    '가까운 분이 그런 상태라면 지켜보는 마음도 많이 무거우실 것 같아요.\n'
    '자살예방 상담전화 109(24시간)는 본인이 아니어도 상담받을 수 있어요. '
    '어떻게 도와야 할지 함께 이야기해 주실 거예요.\n\n'
    '저는 진로 쪽을 도와드리는 곳이라, 필요하시면 그 이야기도 편하게 이어가 주세요.'
)


